function academy_challenge_bank(): array {
    return [
    'me-role'=>[
        ['Ιδιοκτήτης σχεδιάζει αναβάθμιση και προσφέρει τα παλιά πάνελ. Πώς οργανώνεις τη διερεύνηση;','Δύο διακριτά αντικείμενα, με στοιχεία και αξιολόγηση για καθένα.','Ένα lead αγοράς, με το κόστος αναβάθμισης μέσα στην τιμή πάνελ.','Ένα lead υπηρεσίας, θεωρώντας τα παλιά πάνελ συμφωνημένο αντάλλαγμα.','Δύο εγκεκριμένα leads μόλις επιβεβαιωθεί ότι είναι ιδιοκτήτης.','Η κοινή προέλευση δεν ενώνει αντικείμενα ούτε αντικαθιστά τα κριτήρια έγκρισης.'],
        ['Πωλητής ζητά προφορική τιμή σήμερα για να δεσμεύσει 4.000 πάνελ. Έχεις ποσότητα και φωτογραφίες.','Καταγράφω τον χρονικό περιορισμό και ζητώ επίσημη αξιολόγηση.','Δίνω την τιμή της προηγούμενης παρτίδας ως δεσμευτική βάση.','Δεσμεύω την ποσότητα με την επιφύλαξη να αλλάξει μετά η τιμή.','Επιβεβαιώνω αγορά εφόσον οι φωτογραφίες δείχνουν ίδια μοντέλα.','Τα στοιχεία βοηθούν την αξιολόγηση, αλλά δεν δίνουν στον συνεργάτη δικαίωμα εμπορικής δέσμευσης.'],
        ['Βρίσκεις 15 εταιρείες με πάρκα και μία εξουσιοδοτημένη επαφή με συγκεκριμένη διάθεση πάνελ. Τι παραδίδεις;','Τη λίστα ως έρευνα και την επαφή ως ευκαιρία προς τεκμηρίωση.','Δεκαέξι ισοδύναμες ευκαιρίες με διαφορετική προτεραιότητα.','Μόνο τη λίστα, μέχρι να έχει υπογραφεί σύμβαση αγοράς.','Την επαφή ως ολοκληρωμένη αγορά και τις υπόλοιπες ως έρευνα.','Έρευνα, εμπορική ευκαιρία και αγορά είναι διαφορετικά επίπεδα τεκμηρίωσης.']
    ],
    'me-sourcing'=>[
        ['Συντηρητής δίνει ακριβή μοντέλα και ποσότητες, αλλά δεν ξέρει αν ο ιδιοκτήτης πουλά. Ποιο κενό προηγείται;','Επιβεβαίωση πρόθεσης και εξουσιοδοτημένου πωλητή.','Έκπτωση στην τιμή ώστε να αυξηθεί η πιθανότητα αγοράς.','Περισσότερες φωτογραφίες πριν ελεγχθεί η διάθεση.','Αλλαγή του συντηρητή σε ιδιοκτήτη στην καρτέλα.','Η τεχνική γνώση δεν αποδεικνύει πρόθεση ή αρμοδιότητα πώλησης.'],
        ['Έχουν δηλωθεί περίπου 2.500 πάνελ 280 W, αλλά δεν έχουν σταλεί φωτογραφίες. Ποια σημείωση είναι ακριβής;','Εκτίμηση πωλητή 2.500 τεμάχια, φωτογραφίες σε αναμονή.','Επιβεβαιωμένα 2.500 τεμάχια σε καλή κατάσταση.','2.500 διαθέσιμα τεμάχια, χωρίς καμία άλλη εκκρεμότητα.','Μηδενική ποσότητα μέχρι να φωτογραφηθεί κάθε πάνελ.','Η εκτίμηση καταγράφεται ως τέτοια, μαζί με τα αποδεικτικά που λείπουν.'],
        ['Δύο εγκαταστάσεις προσφέρουν 1.000 και 1.500 πάνελ διαφορετικού μοντέλου. Ποια καταγραφή βοηθά;','Ποσότητα, τύπος, κατάσταση και τοποθεσία για κάθε παρτίδα.','2.500 τεμάχια με μέση ισχύ και την πρώτη τοποθεσία.','Η μεγαλύτερη παρτίδα, ώστε η προσφορά να είναι ενιαία.','Δύο ίσες ποσότητες για να μοιραστεί το κόστος μεταφοράς.','Οι επιμέρους ιδιότητες επηρεάζουν αξιολόγηση και παραλαβή· ο μέσος όρος κρύβει κρίσιμες διαφορές.']
    ],
    'me-services'=>[
        ['Ο πελάτης αναφέρει χόρτα, ρύπανση και χαμηλή παραγωγή. Πώς επιλέγεις υπηρεσία;','Διευκρινίζω συμπτώματα και ζητούμενο πριν οριστεί το αντικείμενο.','Επιλέγω καθαρισμό, επειδή είναι η απλούστερη παρέμβαση.','Επιλέγω repowering, επειδή η παραγωγή έχει πέσει.','Επιλέγω την υπηρεσία με τη μεγαλύτερη πιθανή αμοιβή.','Το σύμπτωμα δεν είναι τεχνική διάγνωση ή απόδειξη για μία συγκεκριμένη υπηρεσία.'],
        ['Για πώληση πάρκου €900.000, η επιλέξιμη αμοιβή MELAS που εισπράχθηκε είναι €12.000. Με συμφωνημένο 12%, ποια είναι η βάση;','Τα €12.000 της επιλέξιμης αμοιβής.','Τα €900.000 της αξίας του πάρκου.','Το υπόλοιπο της αξίας μετά την αμοιβή MELAS.','Το άθροισμα αξίας πάρκου και αμοιβής MELAS.','Η προμήθεια υπηρεσίας 10 υπολογίζεται στην εγκεκριμένη επιλέξιμη αμοιβή της MELAS, όχι στην αξία του ακινήτου ή έργου.'],
        ['Ζητείται αναβάθμιση μαζί με πώληση παλιών πάνελ. Ποια πληροφορία κρατάς χωριστή;','Το scope υπηρεσίας από την ποσότητα και τους όρους αγοράς εξοπλισμού.','Την ίδια ανάγκη σε δύο αντίγραφα για δύο αμοιβές lead.','Μόνο τα στοιχεία επικοινωνίας χωρίς περιγραφή αντικειμένων.','Την προμήθεια πάνελ ως έκπτωση στην υπηρεσία.','Διακριτές πραγματικές ευκαιρίες αξιολογούνται χωριστά, όχι αντίγραφα της ίδιας υπόθεσης.']
    ],
    'me-qualification'=>[
        ['Έχεις αρμόδιο, ποσότητα, στοιχεία και πρόθεση πώλησης, αλλά όχι αποδοχή επικοινωνίας με MELAS. Τι ακολουθεί;','Συμπλήρωση του κριτηρίου πριν ζητηθεί έγκριση πλήρους lead.','Έγκριση λόγω πληρότητας των τεχνικών στοιχείων.','Απόρριψη οριστικά χωρίς δυνατότητα συμπλήρωσης.','Αυτόματη δημιουργία €80 με αναμονή μόνο της αγοράς.','Όλα τα κριτήρια πρέπει να ισχύουν· το ελλιπές lead παραμένει σε αναμονή.'],
        ['Επαφή δέχεται ενημέρωση για καθαρισμό «κάποια στιγμή», χωρίς συγκεκριμένο έργο ή χρόνο.','Καταγράφω prospect και διερευνώ ανάγκη και χρονικό πλαίσιο.','Εγκρίνω υπηρεσία επειδή δέχθηκε επικοινωνία.','Καταγράφω ως συμφωνημένη περιοδική συντήρηση.','Δηλώνω έτοιμη προσφορά με ανοικτή ημερομηνία.','Η αποδοχή ενημέρωσης είναι ένα στοιχείο, όχι πλήρης qualified opportunity.'],
        ['Ένα σωστά επαληθευμένο lead εγκρίνεται, αλλά η αγορά ακυρώνεται λόγω υψηλής τιμής. Τι ισχύει για τα €80;','Παραμένουν οφειλόμενα ως αμοιβή της εγκεκριμένης ευκαιρίας.','Ακυρώνονται μαζί με την αγορά, εφόσον δεν παραλήφθηκαν πάνελ.','Μετατρέπονται σε προκαταβολή για το επόμενο lead.','Καταβάλλονται μόνο αν η εταιρεία μεταπωλήσει εξοπλισμό.','Η αμοιβή lead αφορά την πραγματική ευκαιρία που εγκρίθηκε, όχι την τελική αγορά.']
    ],
    'me-commissions'=>[
        ['Εγκρίθηκε lead 5.000 πάνελ. Πληρώθηκαν στον πωλητή 1.800 και συμφωνήθηκαν άλλα 3.200. Πόσο έχει θεμελιωθεί συνολικά;','€1.160','€3.080','€1.080','€1.880','1.800 × €0,60 + €80 = €1.160. Η υπόλοιπη συμφωνημένη ποσότητα δεν έχει ακόμη πληρωθεί.'],
        ['Μετά την πρώτη πληρωμή 2.000 πάνελ, πληρώνονται άλλα 750. Ποια είναι η πρόσθετη προμήθεια πάνελ;','€450','€530','€1.650','€1.730','750 × €0,60 = €450. Δεν επαναλαμβάνεται η αμοιβή lead και δεν πληρώνεται ξανά η προηγούμενη ποσότητα.'],
        ['Υπογράφηκε αγορά 3.000 πάνελ, ο πωλητής δεν πληρώθηκε και το lead είχε ήδη εγκριθεί. Τι είναι πληρωτέο;','Η αμοιβή lead €80, όχι ακόμη η προμήθεια πάνελ.','€1.800 επειδή η ποσότητα δεσμεύτηκε συμβατικά.','€1.880 επειδή υπάρχουν συμφωνία και έγκριση lead.','Τίποτε πριν από τη μελλοντική μεταπώληση των πάνελ.','Η υπογραφή δεν υποκαθιστά την πληρωμή του πωλητή για την προμήθεια €0,60.']
    ],
    'me-conversation'=>[
        ['Ο υπεύθυνος λέει «στείλε ενημέρωση» αλλά δεν έχει περιγράψει ανάγκη. Ποια συνέχεια είναι ακριβής;','Ρωτώ ποιο θέμα τον αφορά και καταγράφω ό,τι πράγματι συμφωνηθεί.','Δηλώνω qualified γιατί δέχθηκε εταιρικό υλικό.','Στέλνω όλες τις υπηρεσίες και προγραμματίζω μόνος μου κλήση.','Στέλνω μια ενδεικτική γενική πρόταση και αφήνω τη διερεύνηση για όταν απαντήσει.','Η σχετική διευκρίνιση βοηθά· η ευγενική αποδοχή υλικού δεν αρκεί για qualification.'],
        ['Η ανάγκη αφορά καθαρισμό, αλλά ο συνομιλητής δεν αποφασίζει. Πώς κλείνεις την κλήση;','Συμφωνώ τον τρόπο επαφής με τον αρμόδιο και καταγράφω τον ρόλο.','Θεωρώ τον συνομιλητή εξουσιοδοτημένο λόγω τεχνικής γνώσης.','Στέλνω γενική ενημέρωση και περιμένω να την προωθήσει, χωρίς να συμφωνήσω επόμενο βήμα.','Στέλνω την πρόταση στην υποδοχή και χαρακτηρίζω ολοκληρωμένο τον εντοπισμό αρμοδίου.','Η σωστή συνέχεια προϋποθέτει ακριβή αποτύπωση αρμοδιότητας.'],
        ['Στη συνέχεια μιας συζήτησης ο πελάτης ζητά ρητά να σταματήσει η επικοινωνία.','Σταματώ, καταγράφω το αίτημα και ενημερώνω την προβλεπόμενη διαδικασία.','Προτείνω διαφορετικό κανάλι ώστε να μείνει ανοικτή η ευκαιρία.','Αναθέτω τη συνέχεια σε συνάδελφο που δεν έχει καλέσει ακόμη.','Περιμένω λίγες ημέρες και επαναλαμβάνω τη συμφωνημένη κλήση.','Το προηγούμενο ενδιαφέρον δεν αναιρεί το σημερινό σαφές αίτημα διακοπής.']
    ],
    'me-pv-basics'=>[
        ['Έργο 500 kW παρήγαγε 700.000 kWh σε ένα έτος. Ποια ανάγνωση είναι σωστή;','Τα 500 kW περιγράφουν ισχύ και οι 700.000 kWh ενέργεια περιόδου.','Οι 700.000 kWh είναι η ονομαστική ισχύς των πάνελ.','Τα 500 kW είναι η αποθηκευμένη ετήσια ενέργεια.','Οι δύο αριθμοί μετρούν το ίδιο μέγεθος σε διαφορετική κλίμακα.','Η ισχύς δεν ταυτίζεται με την ενέργεια που παράγεται σε χρόνο.'],
        ['Δύο πάνελ έχουν ίδια ονομαστικά Watt. Τι μπορείς να πεις χωρίς πρόσθετα στοιχεία;','Έχουν ίδια ονομαστική ισχύ αναφοράς, όχι κατ’ ανάγκη ίδια ετήσια παραγωγή.','Θα έχουν ίδια ετήσια παραγωγή ανεξαρτήτως εγκατάστασης.','Θα είναι ηλεκτρικά εναλλάξιμα σε κάθε υπάρχον σύστημα.','Θα έχουν ίδια πραγματική κατάσταση αφού συμφωνεί η ετικέτα.','Συνθήκες, κατάσταση και συμβατότητα χρειάζονται χωριστή αξιολόγηση.'],
        ['Πελάτης αναφέρει alarm inverter και ζητά οδηγία για άνοιγμα εξοπλισμού.','Καταγράφω το σύμπτωμα και παραπέμπω σε εξουσιοδοτημένο τεχνικό.','Προτείνω μια δοκιμαστική αποσύνδεση πριν την καταγραφή.','Ζητώ τον κωδικό alarm και δίνω τυπική οδηγία επαναφοράς από παρόμοια προηγούμενη περίπτωση.','Υπόσχομαι συγκεκριμένη αποκατάσταση από τη φωτογραφία του alarm.','Ο εμπορικός ρόλος δεν περιλαμβάνει μη εξουσιοδοτημένες ηλεκτρικές επεμβάσεις ή διάγνωση.']
    ],
    'me-panel-inspection'=>[
        ['Report δείχνει 276 W για δείγμα πάνελ 300 W. Τι τεκμηριώνει;','92% της ονομαστικής ισχύος για το μετρημένο δείγμα υπό τις συνθήκες του report.','92% εγγυημένη παραγωγή κάθε πάνελ της παρτίδας.','8% ετήσια υποβάθμιση όλου του πάρκου.','Αυτόματη εμπορική αποδοχή της παρτίδας.','276/300=92%. Δείγμα, συνθήκες και κριτήρια αποδοχής παραμένουν ξεχωριστά.'],
        ['Πωλητής στέλνει δύο καλά αποτελέσματα για παρτίδα 5.000 και γράφει «tested».','Ζητώ μέθοδο, ημερομηνία, φορέα, ταυτοποίηση και αντιπροσωπευτικότητα δείγματος.','Θεωρώ την παρτίδα ελεγμένη επειδή υπάρχουν αριθμητικά reports.','Ζητώ μόνο μία ακόμη καλή φωτογραφία για επιβεβαίωση.','Χρησιμοποιώ τον μέσο όρο των δύο ως εγγύηση της παρτίδας.','Ο αριθμός χωρίς πλαίσιο δοκιμής και δειγματοληψίας δεν τεκμηριώνει το σύνολο.'],
        ['Μικτή παρτίδα περιλαμβάνει πάνελ με ιστορικό πλημμύρας. Ποια καταγραφή είναι κατάλληλη;','Χωριστοί τύποι, ποσότητες και ιστορικό έκθεσης για ειδική αξιολόγηση.','Ενιαία παρτίδα με μέση ηλικία, αφού οπτικά καθαρίστηκαν.','Όλα κατάλληλα για επαναχρησιμοποίηση με μειωμένη τιμή.','Μόνο η συνολική ποσότητα ώστε να αποφασίσει αργότερα ο μεταφορέας.','Η οπτική εικόνα και η εμπορική έκπτωση δεν αντικαθιστούν αξιολόγηση ιστορικού και κινδύνων.']
    ],
    'me-panel-logistics'=>[
        ['Α: αγορά €20.000 και λοιπά κόστη €5.000. Β: αγορά €22.000 και λοιπά κόστη €1.500. Ίδια αποδεκτή ποσότητα/κατάσταση.','Η Β έχει χαμηλότερο γνωστό κόστος παραλαβής κατά €1.500.','Η Α έχει χαμηλότερο κόστος κατά €2.000.','Οι δύο είναι ισοδύναμες επειδή τα πάνελ είναι ίδια.','Η Β είναι χαμηλότερη κατά €3.500, όση η διαφορά μεταφοράς.','Σύνολα: Α €25.000, Β €23.500. Συγκρίνουμε συνολικά ίδιας βάσης κόστη.'],
        ['Η παραλαβή ορίστηκε Παρασκευή αλλά δεν ξέρουμε ποιος φορτώνει. Ποια είναι η σωστή συνέχεια;','Επιβεβαιώνω εξοπλισμό, πρόσβαση και ευθύνη φόρτωσης πριν δεσμευτώ.','Θεωρώ ότι η μεταφορική καλύπτει κάθε εργασία φόρτωσης.','Υποθέτω ότι ο πωλητής διαθέτει κατάλληλο ανυψωτικό.','Μεταφέρω την εκκρεμότητα στον οδηγό κατά την άφιξη.','Η μη συμφωνημένη ευθύνη δημιουργεί πραγματικό κόστος και κίνδυνο καθυστέρησης.'],
        ['Η τιμή είναι ελκυστική αλλά ο προσφέρων δεν αποδεικνύει δικαίωμα πώλησης.','Παγώνω τη δέσμευση μέχρι να ελεγχθεί η εξουσιοδότηση.','Κλείνω μεταφορική για να προλάβω ανταγωνιστή.','Αρκούμαι σε φωτογραφίες ετικετών ως απόδειξη κυριότητας.','Αντισταθμίζω την αβεβαιότητα με μικρότερη προκαταβολή.','Η νομιμοποίηση του πωλητή δεν υποκαθίσταται από χαμηλή τιμή ή μικρότερη πληρωμή.']
    ],
    'me-construction'=>[
        ['Πελάτης ζητά ημερομηνία κατασκευής αλλά δεν έχουν διευκρινιστεί άδειες και πρόσβαση.','Καταγράφω εξαρτήσεις και ζητώ τεχνική επιβεβαίωση χρονοδιαγράμματος.','Δίνω την ημερομηνία ανάλογου προηγούμενου έργου ως δέσμευση.','Θεωρώ ότι οι άδειες καλύπτονται επειδή υπάρχει ιδιοκτήτης.','Μετατρέπω τον επιθυμητό χρόνο σε συμφωνημένη παράδοση.','Ο χρονικός στόχος πελάτη δεν είναι εγκεκριμένο εκτελέσιμο πρόγραμμα.'],
        ['Ένα BoQ περιγράφει υλικά, αλλά λείπουν ποσότητες και όρια εργασιών. Τι λείπει από την προσφορά;','Επαρκής βάση κοστολόγησης και σαφές scope προς επιβεβαίωση.','Μόνο ο τελικός λογότυπος της πρότασης.','Αποκλειστικά η ημερομηνία υπογραφής του πελάτη.','Μόνο το ύψος της προμήθειας του συνεργάτη.','Η περιγραφή υλικών χωρίς ποσότητες και όρια δεν αρκεί για συγκεκριμένη οικονομική δέσμευση.'],
        ['Ο πελάτης ζητά commissioning και ο συνεργάτης το συνδέει με την αμοιβή του.','Διευκρινίζω ότι commissioning είναι τεχνικός έλεγχος έναρξης λειτουργίας.','Το καταχωρίζω ως προμήθεια με το αγγλικό της όνομα.','Το θεωρώ απόδειξη ότι έχει ήδη πληρωθεί το έργο.','Το χρησιμοποιώ ως συνώνυμο της εμπορικής αποδοχής.','Commissioning και commission είναι διαφορετικές έννοιες.']
    ],
    'me-operations'=>[
        ['Πτώση παραγωγής συμπίπτει με ορατή ρύπανση. Ποια εμπορική διατύπωση είναι τεκμηριωμένη;','Διερευνούμε καθαρισμό και τεχνική αξιολόγηση χωρίς εγγυημένο ποσοστό ανάκτησης.','Ο καθαρισμός θα επαναφέρει όλη την παραγωγή που λείπει.','Η ρύπανση αποδεικνύει ότι δεν υπάρχει άλλο τεχνικό πρόβλημα.','Το repowering είναι υποχρεωτικό επειδή έχει μειωθεί η παραγωγή.','Η συσχέτιση δεν αποδεικνύει μοναδική αιτία ή συγκεκριμένο αποτέλεσμα.'],
        ['Συμφωνήθηκε περιοδική συντήρηση και ο πελάτης ζητά πρόσθετη αναβάθμιση.','Διαχωρίζω το συμφωνημένο O&M από τη νέα ανάγκη προς αξιολόγηση.','Θεωρώ κάθε αναβάθμιση μέρος της υπάρχουσας συντήρησης.','Κλείνω την τρέχουσα σύμβαση για να φαίνεται μόνο νέο έργο.','Αποδίδω αυτόματα δεύτερη αμοιβή lead για την ίδια εργασία.','Η νέα ανάγκη χρειάζεται σαφή όρια χωρίς διπλή αποτύπωση του ίδιου αντικειμένου.'],
        ['Πάρκο ζητά αποψίλωση και καθαρισμό με πρόσβαση μόνο συγκεκριμένες ώρες.','Καταγράφω επιφάνεια, πρόσβαση, χρονικά όρια και scope για σχεδιασμό εργασιών.','Υπολογίζω κόστος μόνο από τη συνολική ισχύ του πάρκου.','Θεωρώ τις ώρες πρόσβασης θέμα που θα λυθεί επί τόπου.','Δηλώνω σταθερή ημερομηνία πριν απαντήσει η τεχνική ομάδα.','Οι συνθήκες πρόσβασης και το συγκεκριμένο αντικείμενο επηρεάζουν εκτέλεση και κόστος.']
    ],
    'me-special-services'=>[
        ['Μεσολαβητής προτείνει λειτουργούν πάρκο χωρίς σαφή εντολή ιδιοκτήτη.','Ελέγχω αρμοδιότητα και διαθέσιμη τεκμηρίωση πριν παρουσιαστεί ως ώριμη πώληση.','Αρκούμαι στην ισχύ και στην τιμή για να το εγκρίνω.','Θεωρώ την κατοχή φωτογραφιών ισοδύναμη με εντολή.','Υπολογίζω προμήθεια στην αξία του πάρκου πριν την επαλήθευση.','Η πραγματική εξουσιοδότηση είναι διαφορετική από την απλή γνώση μιας εγκατάστασης.'],
        ['Ιδιοκτήτης κατοικίας ζητά βέβαιη εξοικονόμηση από μια φωτογραφία στέγης.','Ζητώ κατανάλωση και στοιχεία εγκατάστασης για τεχνική αξιολόγηση.','Δίνω δεσμευτική εκτίμηση με βάση την επιφάνεια στέγης και τη μέση οικιακή κατανάλωση.','Χρησιμοποιώ την απόδοση γειτονικού έργου ως δεσμευτική.','Υπόσχομαι πλήρη κάλυψη επειδή η στέγη φαίνεται μεγάλη.','Χώρος, κατανάλωση και τεχνικές συνθήκες πρέπει να αξιολογηθούν.'],
        ['Πελάτης ενδιαφέρεται και για αγορά πάρκου και για οικιακό σύστημα.','Καταγράφω ξεχωριστά στόχο, αρμοδιότητα και δεδομένα κάθε ανάγκης.','Κρατώ μία γενική ευκαιρία και αφήνω τον διαχωρισμό αναγκών για μετά την πρώτη πρόταση.','Επιλέγω μόνο τη μεγαλύτερη αξία επειδή ο πελάτης είναι ίδιος.','Εγκρίνω και τα δύο από την ίδια γενική συγκατάθεση ενημέρωσης.','Η κοινή επαφή δεν καταργεί τη διακριτή τεκμηρίωση των αντικειμένων.']
    ],
    'me-research'=>[
        ['Ανακοίνωση repowering αναφέρει έργο, όχι πωλητή ή διαθέσιμη ποσότητα.','Τη χρησιμοποιώ ως trigger για επαλήθευση αρμοδίου και διάθεσης.','Τη θεωρώ έτοιμη ευκαιρία αγοράς όλης της παλιάς εγκατάστασης.','Την υποβάλλω ως πληρωτέο lead επειδή είναι δημόσια.','Εκτιμώ διαθέσιμη ποσότητα από την εγκατεστημένη ισχύ και υποβάλλω πριν επιβεβαιωθεί ποιος πουλά.','Το trigger ξεκινά έρευνα και δεν αποδεικνύει από μόνο του εμπορική ευκαιρία.'],
        ['Έχεις γενικό email εταιρείας και όνομα υπεύθυνου συντήρησης. Ποιο επόμενο βήμα έχει αξία;','Επιβεβαίωση ποιος χειρίζεται το συγκεκριμένο αντικείμενο και πώς προσεγγίζεται.','Μαζική αποστολή της ίδιας πρότασης σε κάθε εργαζόμενο.','Ανάθεση αρμοδιότητας πώλησης στον τεχνικό στην καρτέλα.','Σημείωση ότι έγινε discovery επειδή βρέθηκε ένα όνομα.','Σωστός άνθρωπος σημαίνει επιβεβαιωμένος ρόλος για το συγκεκριμένο ζήτημα.'],
        ['Δύο πηγές δίνουν διαφορετική ποσότητα για το ίδιο πάρκο.','Κρατώ πηγή και αβεβαιότητα και ζητώ επιβεβαίωση από τον αρμόδιο.','Χρησιμοποιώ τη μεγαλύτερη επειδή είναι εμπορικά ελκυστική.','Βγάζω μέσο όρο και τον δηλώνω επιβεβαιωμένο.','Χρησιμοποιώ τη νεότερη δημοσίευση ως επιβεβαιωμένη ποσότητα, κρατώντας σύνδεσμο προς την παλαιότερη.','Αντικρουόμενες πληροφορίες χρειάζονται επίλυση, όχι αριθμητικό συμβιβασμό ή διπλοεγγραφή.']
    ],
    'me-discovery'=>[
        ['Ο συνομιλητής λέει «θέλουμε καλύτερη παραγωγή» χωρίς άλλη πληροφορία.','Ρωτώ σημερινή κατάσταση, διαφορά που παρατηρεί και επιθυμητό αποτέλεσμα.','Προτείνω αμέσως αλλαγή πάνελ ως ολοκληρωμένη διάγνωση.','Δίνω ποσοστό βελτίωσης από παλιότερο έργο.','Καταγράφω αίτημα αγοράς νέου εξοπλισμού ως επιβεβαιωμένο.','Η γενική επιθυμία δεν προσδιορίζει ακόμη αιτία ή κατάλληλη παρέμβαση.'],
        ['Υπάρχει τεχνική ανάγκη αλλά δεν ξέρουμε ποιος εγκρίνει τη δαπάνη.','Συμπληρώνω τη διαδικασία απόφασης πριν θεωρήσω εμπορικά ώριμη την υπόθεση.','Θεωρώ ότι ο τεχνικός εγκρίνει επειδή περιέγραψε το πρόβλημα.','Παραλείπω το θέμα μέχρι να ολοκληρωθεί η εργασία.','Αυξάνω την πιθανότητα πώλησης μόνο βάσει της σοβαρότητας.','Τεχνική ανάγκη και οικονομική αρμοδιότητα είναι ξεχωριστές κατηγορίες discovery.'],
        ['Ο πελάτης διορθώνει τη σύνοψή σου: χρειάζεται επιθεώρηση, όχι καθαρισμό.','Ενημερώνω τη σύνοψη και επιβεβαιώνω το νέο επόμενο βήμα.','Κρατώ τον καθαρισμό ως κύριο αντικείμενο και προσθέτω την επιθεώρηση ως συμπληρωματική υπόθεση.','Καταγράφω και τα δύο ως συμφωνημένες υπηρεσίες.','Μεταφέρω την αλλαγή προφορικά στον υπεύθυνο και αφήνω την καρτέλα για αργότερα.','Η παράφραση χρησιμεύει ακριβώς για να διορθώνεται η κατανόηση πριν την πρόταση.']
    ],
    'me-objections'=>[
        ['«Η προσφορά είναι ακριβή» χωρίς εξήγηση. Ποια πρώτη κίνηση βοηθά περισσότερο;','Διευκρινίζω αν συγκρίνει άλλο scope, διαθέσιμο ποσό ή αντιλαμβανόμενη αξία.','Προσφέρω έκπτωση πριν εξετάσω την αιτία.','Εξηγώ ξανά όλο το ιστορικό της εταιρείας.','Αυξάνω την πίεση αναφέροντας ότι η τιμή λήγει σήμερα.','Η σωστή απάντηση εξαρτάται από την πραγματική αιτία της επιφύλαξης.'],
        ['Ο πελάτης έχει συνεργάτη αλλά αναφέρει καθυστερήσεις.','Διερευνώ συγκεκριμένο κενό και πιθανή συμπληρωματική ανάγκη χωρίς απαξίωση.','Προτείνω να ακυρώσει τη συνεργασία πριν δούμε τα δεδομένα.','Υπόσχομαι ταχύτερη παράδοση χωρίς έλεγχο διαθεσιμότητας.','Καταγράφω κερδισμένη υπόθεση λόγω δυσαρέσκειας.','Η δυσαρέσκεια μπορεί να ανοίξει συζήτηση, όχι αυτόματη ανάθεση ή τεχνική δέσμευση.'],
        ['«Δεν είναι προτεραιότητα τώρα, μιλήστε μου τον Δεκέμβριο».','Επιβεβαιώνω σχετικό χρόνο και σκοπό και καταγράφω τη συμφωνημένη συνέχεια.','Καταγράφω άμεση ευκαιρία με τρέχουσα ημερομηνία.','Καλώ εβδομαδιαία ώστε να διατηρηθεί ζεστή η επαφή.','Απορρίπτω οριστικά χωρίς σημείωση της μελλοντικής επιθυμίας.','Η συνέχεια ακολουθεί τον συμφωνημένο χρονισμό, χωρίς να επινοεί άμεση ωριμότητα.']
    ],
    'me-negotiation'=>[
        ['Ζητείται χαμηλότερη τιμή με ίδιο scope και συντομότερο χρόνο.','Καταγράφω το αίτημα και ελέγχω εγκεκριμένες εναλλακτικές και ανταλλάγματα.','Δέχομαι και τα δύο για να κλείσω πριν τον ανταγωνιστή.','Στέλνω μικρότερο scope στην τεχνική ομάδα, θεωρώντας ότι η αποδοχή της έκπτωσης καλύπτει τη διαφορά.','Υποθέτω ότι η τεχνική ομάδα θα απορροφήσει τη διαφορά.','Παραχωρήσεις, scope και χρονοδιάγραμμα απαιτούν σαφή συμφωνία και εξουσιοδότηση.'],
        ['Ο πελάτης λέει «μάλλον θα προχωρήσουμε» αλλά λείπει η τελική έγκριση.','Καταγράφω θετική ένδειξη και επόμενη ενέργεια για την απόφαση.','Δηλώνω WON για να αρχίσει η υλοποίηση.','Θεωρώ ότι αποδέχθηκε όλους τους οικονομικούς όρους.','Μεταφέρω την υπόθεση σε αποδεκτή πρόταση και αφήνω ανοικτή μόνο την ημερομηνία έναρξης.','Πρόθεση, έγκριση, ανάθεση και πληρωμή δεν είναι το ίδιο γεγονός.'],
        ['Δύο προσφορές έχουν διαφορετική έκταση υπηρεσιών. Πριν συζητηθεί έκπτωση…','Ευθυγραμμίζω scope, εξαιρέσεις, ευθύνες και όρους σύγκρισης.','Συγκρίνω μόνο το τελικό ποσό χωρίς επιπλέον ερωτήσεις.','Αφαιρώ τη συντήρηση ώστε να ταιριάξουν οι αριθμοί σιωπηρά.','Χαρακτηρίζω τη φθηνότερη προσφορά λανθασμένη χωρίς στοιχεία.','Η διαπραγμάτευση χρειάζεται κοινή βάση σύγκρισης και όχι μόνο τελική τιμή.']
    ],
    'me-written'=>[
        ['Μετά από συζήτηση για ρύπανση, ποιο email εξυπηρετεί καλύτερα τη συνέχεια;','Σύντομη σύνοψη ανάγκης, ζητούμενα στοιχεία και συμφωνημένο επόμενο βήμα.','Όλος ο κατάλογος υπηρεσιών χωρίς αναφορά στη συζήτηση.','Δεσμευτική τιμή χωρίς δεδομένα έκτασης ή πρόσβασης.','Γενικό μήνυμα «περιμένω νέα σας» χωρίς συγκεκριμένο αίτημα.','Το γραπτό μήνυμα συνεχίζει την πραγματική συζήτηση και καθιστά σαφή τη συνέχεια.'],
        ['Ο παραλήπτης ζήτησε μόνο τα στοιχεία μιας υπηρεσίας.','Στέλνω το σχετικό ζητημένο υλικό και καταγράφω τον σκοπό.','Τον εντάσσω και σε περιοδικές καμπάνιες άλλων υπηρεσιών.','Προωθώ την επαφή σε τρίτους για περισσότερες προσφορές.','Θεωρώ το αίτημα γενική αποδοχή κάθε καναλιού επικοινωνίας.','Το συγκεκριμένο αίτημα δεν ισοδυναμεί με απεριόριστη χρήση της επαφής.'],
        ['Έχεις στείλει 20 ενημερωτικά μηνύματα χωρίς απάντηση. Τι αναφέρεις;','20 αποστολές, χωρίς ακόμη επιβεβαιωμένες εμπορικές ευκαιρίες.','20 qualified leads με χαμηλό επίπεδο ενδιαφέροντος.','20 ενεργές προτάσεις με άγνωστη ημερομηνία αποδοχής.','20 εγκεκριμένες επαφές επειδή τα email παραδόθηκαν.','Η δραστηριότητα αποστολής δεν αποδεικνύει πρόθεση ή ανάγκη.']
    ],
    'me-account-growth'=>[
        ['Έγιναν 20 ουσιαστικές συζητήσεις και προέκυψαν 5 qualified leads. Ποιο ποσοστό περιγράφει αυτό το βήμα;','25%','20%','5%','80%','5/20 ×100 =25%. Χρησιμοποιούμε τον παρονομαστή της συγκεκριμένης διαδρομής.'],
        ['Συνεργάτης δικαιούται €3.000 commission και υπάρχει διαφορετικός έγκυρος Team Leader με override 10%.','Ο συνεργάτης κρατά €3.000 και ο Team Leader δικαιούται πρόσθετα €300.','Ο συνεργάτης παίρνει €2.700 και ο Team Leader €300.','Ο Team Leader παίρνει 10% της αξίας του συνολικού έργου.','Η προμήθεια μοιράζεται €1.500 στον καθένα.','Το override αφορά την προμήθεια και είναι πρόσθετο, υπό τις εγκεκριμένες προϋποθέσεις.'],
        ['Επαναλαμβάνεται καθαρισμός υπάρχοντος πελάτη με εγκεκριμένη πολιτική 10%.','Εφαρμόζω την πολιτική στην επιλέξιμη βάση, χωρίς αυτόματο νέο lead fee.','Μειώνω αυτόματα το ποσοστό επειδή είναι παλιός πελάτης.','Δημιουργώ νέο €80 σε κάθε περιοδική επίσκεψη.','Υπολογίζω την προμήθεια στη συνολική αξία του πάρκου.','Η επανάληψη υπηρεσίας δεν αλλάζει μόνη της το ποσοστό ούτε γεννά νέα αμοιβή qualified lead.']
    ],
    ] + academy_technology_challenges() + academy_b2b_challenges();
}

function academy_technology_challenges(): array {
 return [
 'di-positioning'=>[
 ['Εταιρεία ζητά «AI» χωρίς να περιγράφει πρόβλημα. Ποια πρώτη συνέχεια επιλέγεις;','Ρωτώ ποια εργασία δυσκολεύει, τι δεδομένα υπάρχουν και ποιο αποτέλεσμα θέλει.','Προτείνω μοντέλο πριν συζητηθούν δεδομένα και κριτήρια.','Δίνω σταθερό ποσοστό αυτοματοποίησης από προηγούμενο έργο.','Καταγράφω ως συμφωνημένη ανάπτυξη νέας εφαρμογής.','Η τεχνολογία ακολουθεί το επιχειρηματικό πρόβλημα, όχι το αντίστροφο.'],
 ['Υπάρχει εσωτερική ομάδα αλλά λείπει δυναμικότητα για συγκεκριμένο module.','Διερευνώ οριοθετημένο work package ή συμφωνημένη τεχνική δυναμικότητα.','Προτείνω μόνο πλήρη αντικατάσταση της εσωτερικής ομάδας.','Θεωρώ ότι δεν υπάρχει κατάλληλη συνεργασία.','Υπόσχομαι απεριόριστη υποστήριξη μαζί με το module.','Η συνεργασία μπορεί να αφορά μέρος έργου ή δυναμικότητα, με σαφή όρια.'],
 ['Ο ίδιος συνεργάτης εργάζεται και στις δύο εταιρείες. Τι ισχύει για τις αμοιβές Distillogic;','Χρειάζονται οι δικοί της εγκεκριμένοι εμπορικοί όροι.','Ισχύει αυτόματα το €80 κάθε lead της MELAS.','Ισχύει προμήθεια πάνελ επειδή είναι ίδιος λογαριασμός.','Η ολοκλήρωση του κοινού Academy αρκεί για κοινό τιμολόγιο.','Κοινή πρόσβαση και εκπαίδευση δεν ενοποιούν εταιρικές πολιτικές.']
 ],
 'di-services'=>[
 ['Η επιχείρηση αντιγράφει παραγγελίες ανάμεσα σε δύο υπάρχοντα συστήματα.','Διερευνώ διασύνδεση συστημάτων και τις διαθέσιμες διεπαφές.','Προτείνω αμέσως νέο website ως μοναδική λύση.','Θεωρώ ότι πρέπει να αντικατασταθούν και τα δύο συστήματα.','Υπόσχομαι διασύνδεση επειδή λειτουργούν στο διαδίκτυο.','Το σύμπτωμα δείχνει πιθανή ανάγκη integration, αλλά η εφικτότητα ελέγχεται.'],
 ['Υπάρχουσα εφαρμογή χρειάζεται διορθώσεις, εκδόσεις και λειτουργική εξέλιξη.','Εξετάζω Application Management με σαφείς ευθύνες και απαιτήσεις.','Καταγράφω αποκλειστικά νέα κατασκευή από μηδενική βάση.','Υπόσχομαι αποκατάσταση κάθε σφάλματος εντός ώρας.','Προτείνω απλό πακέτο hosting ως πλήρη κάλυψη της συντήρησης και εξέλιξης της εφαρμογής.','Η διαχείριση κύκλου ζωής διαφέρει από ένα νέο πλήρες έργο.'],
 ['Ζητείται AI με 99% ακρίβεια χωρίς διαθέσιμο αντιπροσωπευτικό δείγμα.','Καταγράφω τον στόχο ως απαίτηση προς αξιολόγηση, όχι εγγύηση.','Δέχομαι το ποσοστό επειδή το ζήτησε ο πελάτης.','Το μετατρέπω σε συμβατική δέσμευση με μεγαλύτερη τιμή.','Θεωρώ ότι ένα δοκιμαστικό παράδειγμα αποδεικνύει την ακρίβεια.','Δεδομένα, δοκιμές και κριτήρια αποδοχής χρειάζονται τεχνική επιβεβαίωση.']
 ],
 'di-delivery'=>[
 ['Ο πελάτης θέλει συγκεκριμένο module, αλλά προσθέτει εβδομαδιαία νέες απαιτήσεις.','Οριοθετώ το συμφωνημένο scope και δρομολογώ αξιολόγηση αλλαγών.','Θεωρώ κάθε νέα απαίτηση δωρεάν μέρος του αρχικού module.','Κρατώ την αρχική ημερομηνία ανεξαρτήτως αλλαγών.','Μετατρέπω μόνος μου το μοντέλο σε απεριόριστη υποστήριξη.','Fixed scope προϋποθέτει όρια και ελεγχόμενη διαχείριση αλλαγών.'],
 ['Η ομάδα πελάτη ζητά δύο ειδικότητες για μεταβαλλόμενες προτεραιότητες.','Διερευνώ χρόνο, ρόλους και διαθεσιμότητα σε μοντέλο δυναμικότητας.','Δεσμεύω τελικό παραδοτέο χωρίς να γνωρίζω τις απαιτήσεις.','Θεωρώ ότι πρόκειται μόνο για εφάπαξ website.','Εγγυώμαι το σύνολο των μελλοντικών λειτουργιών με μία τιμή.','Το μοντέλο δυναμικότητας χρειάζεται συμφωνημένους ρόλους και τρόπο συνεργασίας.'],
 ['Module εξαρτάται από API τρίτου που δεν έχει ακόμη παραδοθεί.','Καταγράφω την εξάρτηση και την επίδρασή της στο πλάνο.','Θεωρώ την καθυστέρηση εντός της δικής μας εγγύησης.','Προγραμματίζω ως ολοκληρωμένο το module με προσωρινά δεδομένα και κρατώ αμετάβλητη την ημερομηνία τελικής αποδοχής.','Δηλώνω το module έτοιμο για αποδοχή πριν τον έλεγχο.','Οι εξαρτήσεις επηρεάζουν τεχνικό σχεδιασμό, κόστος και χρόνο.']
 ],
 'di-discovery'=>[
 ['Brief γράφει «θέλει σύστημα πελατών σύντομα». Τι χρειάζεται πρώτο;','Ροές χρηστών, σημερινή δυσκολία, απαιτούμενο αποτέλεσμα και περιορισμοί.','Επιλογή τεχνολογίας και ημερομηνία παράδοσης χωρίς άλλες ερωτήσεις.','Μόνο ο αριθμός τηλεφώνου για να ξεκινήσει η ανάπτυξη.','Ένα γενικό PDF τιμοκαταλόγου ως τελική προσφορά.','Το αξιοποιήσιμο discovery ορίζει πρόβλημα, χρήστες, όρια και ανοικτά ζητήματα.'],
 ['Ο πελάτης στέλνει production password για πρώτη αξιολόγηση.','Δεν το χρησιμοποιώ· ακολουθώ ασφαλή εγκεκριμένη διαδικασία και ζητώ μη ευαίσθητη τεκμηρίωση.','Το αντιγράφω στο κοινό πεδίο σημειώσεων για την ομάδα.','Το δοκιμάζω για να επιβεβαιώσω ότι λειτουργεί.','Το προωθώ σε προσωπικό email ώστε να μην χαθεί.','Το αρχικό discovery δεν απαιτεί ανεξέλεγκτη διαχείριση μυστικών παραγωγής.'],
 ['Ζητείται SLA που δεν έχει επιβεβαιωθεί από την ομάδα.','Το καταγράφω ως ζητούμενο προς συμφωνία με τις σχετικές προϋποθέσεις.','Το παρουσιάζω ως διαθέσιμο επειδή ακούγεται συνηθισμένο.','Χρησιμοποιώ το SLA προηγούμενου έργου ως βασικό όρο και ζητώ έλεγχο μόνο αν προκύψει ένσταση.','Το δέχομαι εφόσον η βασική τιμή παραμένει ίδια.','Η απαίτηση του πελάτη δεν είναι ήδη εγκεκριμένος εταιρικός όρος.']
 ],
 'crm-orientation'=>[
 ['Αλλάζεις CRM με τον διακόπτη και δεν βρίσκεις την επαφή που δημιούργησες στη MELAS.','Ελέγχω αν βρίσκομαι σε άλλο εταιρικό περιβάλλον πριν δημιουργήσω νέα εγγραφή.','Θεωρώ ότι η αλλαγή απέτυχε και εισάγω όλο το πελατολόγιο.','Υποθέτω ότι οι επαφές πρέπει να συγχρονίζονται αυτόματα.','Ζητώ τον κωδικό διαχειριστή για να δω την κρυμμένη επαφή.','Η εναλλαγή περιβάλλοντος δεν αντιγράφει δεδομένα ούτε διευρύνει δικαιώματα.'],
 ['Sales Partner χρειάζεται συνολικά οικονομικά όλων για μια παρουσίαση.','Ζητά εγκεκριμένη συγκεντρωτική αναφορά από τον αρμόδιο.','Αλλάζει παραμέτρους CSV για να εμφανιστούν ξένοι δικαιούχοι.','Χρησιμοποιεί λογαριασμό συναδέλφου με μεγαλύτερη πρόσβαση.','Θεωρεί ότι η Academy του έδωσε σχετική εξουσιοδότηση.','Η εργασία δεν παρακάμπτει την προσωπική οικονομική πρόσβαση.'],
 ['Η σελίδα σύνδεσης ανοίγει με προειδοποίηση μη ασφαλούς σύνδεσης.','Σταματώ την εισαγωγή κωδικού και ζητώ ασφαλή σωστή διεύθυνση.','Συνεχίζω επειδή αναγνωρίζω το λογότυπο.','Χρησιμοποιώ προσωρινά τον ίδιο κωδικό χωρίς αυτόματη αποθήκευση.','Στέλνω τον κωδικό σε συνάδελφο για να δοκιμάσει.','Το οικείο περιεχόμενο δεν εξασφαλίζει κρυπτογραφημένη αξιόπιστη σύνδεση.']
 ],
 'crm-entry'=>[
 ['Ζητούνται €54.000 για 2.700 πάνελ. Ποια τιμή ανά πάνελ ελέγχεις;','€20','€18','€22','€27','54.000 / 2.700 =20. Η ζητούμενη τιμή παραμένει διαφορετική από συμφωνία ή πληρωμή.'],
 ['Καταχώρισες lead και ο διαχειριστής το εγκρίνει. Ποιος κρατά την ιδιοκτησία;','Ο αρχικός καταχωρητής· η έγκριση δεν μεταβιβάζει το lead.','Ο εγκρίνων, επειδή αναλαμβάνει την εταιρική επικοινωνία.','Ο χρήστης που θα κάνει το επόμενο τηλεφώνημα.','Ο πρώτος που θα καταγράψει πραγματική πληρωμή.','Η αρχική προέλευση προστατεύεται ανεξάρτητα από το ποιος αξιολογεί.'],
 ['Ο αξιολογητής ζητά ακριβέστερη ποσότητα.','Συμπληρώνω την ίδια εγγραφή και επανυποβάλλω με το ιστορικό της.','Δημιουργώ νέο lead ώστε να εμφανίζεται πλήρες από την αρχή.','Αλλάζω μόνο την ποσότητα, χωρίς να σημειώσω από πού προήλθε η νέα επιβεβαίωση.','Στέλνω τη νέα ποσότητα με email στον εγκρίνοντα και αφήνω την υπάρχουσα καρτέλα αμετάβλητη.','Η ίδια υπόθεση κρατά προέλευση και συνέχεια· δεν διορθώνεται με διπλότυπο.']
 ],
 'crm-protection'=>[
 ['Αξιολογητής θέλει τηλέφωνο πριν αποδεχθεί κατοχύρωση και αμοιβή.','Συνεχίζει με τα επιτρεπόμενα ανώνυμα στοιχεία μέχρι την προβλεπόμενη αποδοχή.','Το παίρνει από το CSV χωρίς να ανοίξει την καρτέλα.','Ζητά από άλλο υπάλληλο να του στείλει το αποδεικτικό.','Αλλάζει προσωρινά την ανάθεση για να εμφανιστεί η επαφή.','Η προστασία ισχύει σε όλες τις διαδρομές και όχι μόνο στην οθόνη.'],
 ['Έγινε η ενιαία αποδοχή του lead. Ποιος συνδυασμός περιγράφει το γεγονός;','Αμοιβή €80 πληρωτέα και προβλεπόμενη αποκάλυψη στοιχείων.','Αποκάλυψη τώρα και δικαίωμα €80 μόνο μετά την αγορά.','Πραγματική τραπεζική εξόφληση €80 και όλων των προμηθειών.','Μεταβίβαση ιδιοκτησίας στον αξιολογητή με αποκάλυψη.','Η αποδοχή συνδέει αμοιβή και πρόσβαση, χωρίς να ισοδυναμεί με τραπεζική πληρωμή.'],
 ['Το αποδεικτικό εμφανίζει πληρωτέα αμοιβή. Τι μπορείς να συμπεράνεις;','Ότι το CRM κατέγραψε το δικαίωμα, όχι ότι εκτελέστηκε τραπεζική μεταφορά.','Ότι το ποσό έχει ήδη κατατεθεί στον δικαιούχο.','Ότι έγινε και η αγορά όλων των αρχικά εκτιμώμενων πάνελ.','Ότι δεν απαιτείται κανένας έλεγχος με τα οικονομικά στοιχεία.','Το αποδεικτικό τεκμηριώνει καταχωρίσεις και ιστορικό.']
 ],
 'crm-finance'=>[
 ['Πληρώθηκαν 2.000 πάνελ στον πωλητή, αλλά όχι ο συνεργάτης. Το lead είχε εγκριθεί.','€1.280 θεμελιωμένα, με εξόφληση συνεργάτη ακόμη εκκρεμή.','€1.280 εξοφλημένα, αφού πληρώθηκε ο πωλητής.','Μόνο €80 θεμελιωμένα μέχρι τη μεταπώληση.','€1.200 συνολικά, επειδή η αγορά αντικαθιστά το lead fee.','2.000×0,60+80=1.280. Θεμελίωση και εξόφληση συνεργάτη είναι διαφορετικά γεγονότα.'],
 ['Στην αναφορά υπάρχει διαφορά €300 από τον δικό σου υπολογισμό.','Ζητώ έλεγχο με lead, πληρωμένη ποσότητα και σχετική καταχώριση.','Προσθέτω δεύτερη πληρωμή για να ισορροπήσει το ποσό.','Αλλάζω την αρχική ποσότητα ώστε να προκύπτει το αναμενόμενο.','Δημιουργώ νέο lead με το ποσό που λείπει.','Η διαφορά διορθώνεται με τεκμηρίωση και εξουσιοδοτημένη ενέργεια.'],
 ['Το CSV ενός συνεργάτη περιέχει οικονομικά άλλου. Ποια αντίδραση είναι σωστή;','Σταματά τη διανομή και ενημερώνει τον διαχειριστή για έλεγχο πρόσβασης.','Το θεωρεί επιτρεπτό επειδή είναι εξαγωγή και όχι σελίδα.','Το κρατά για σύγκριση προσωπικής απόδοσης.','Το προωθεί στην ομάδα ώστε να ελεγχθεί από όλους.','Τα ίδια δικαιώματα ισχύουν στις εξαγωγές· το λάθος δεν νομιμοποιεί χρήση.']
 ],
 'crm-proposals'=>[
 ['Εγκρίθηκε PDF, αλλά πριν σταλεί αλλάζει το τίμημα.','Δημιουργείται νέα έκδοση και ζητείται νέα έγκριση.','Αλλάζει μόνο το συνημμένο με την προηγούμενη έγκριση.','Στέλνεται το νέο ποσό στο email και το παλιό PDF.','Χρησιμοποιείται ο ίδιος κωδικός έγκρισης για όλη την εταιρεία.','Η έγκριση αφορά συγκεκριμένο περιεχόμενο και έκδοση.'],
 ['Sales Partner ολοκλήρωσε όλα τα μαθήματα προτάσεων.','Εξακολουθεί να χρησιμοποιεί μόνο τις λειτουργίες που επιτρέπει ο πραγματικός ρόλος του.','Αποκτά αυτόματα δικαίωμα αποστολής εγκεκριμένων PDF.','Μπορεί να εγκρίνει δικά του έγγραφα αν πέρασε με 100%.','Μπορεί να αναθέτει στον εαυτό του οικονομικά δικαιώματα.','Η εκπαίδευση δεν αποτελεί αλλαγή εξουσιοδότησης.'],
 ['Ο πελάτης έλαβε εγκεκριμένη πρόταση, αλλά δεν απάντησε.','Καταγράφεται αποστολή και η συμφωνημένη συνέχεια, όχι αποδοχή.','Η υπόθεση χαρακτηρίζεται WON επειδή εγκρίθηκε από CEO.','Η αμοιβή πάνελ θεμελιώνεται από το email αποστολής.','Η σιωπή θεωρείται συμφωνία όλων των όρων.','Εσωτερική έγκριση, αποστολή και αποδοχή πελάτη είναι διαφορετικά στάδια.']
 ],
 'dcrm-orientation'=>[
 ['Μια εταιρεία έχει τρεις συζητήσεις για δύο διαφορετικά έργα.','Κρατώ την εταιρική ταυτότητα και διακριτές σχετικές επικοινωνίες/αντικείμενα.','Δημιουργώ τρεις διαφορετικές εταιρείες για κάθε τηλεφώνημα.','Συγχωνεύω τα δύο έργα επειδή το email επαφής είναι ίδιο.','Χρησιμοποιώ την προσωπική οικονομική καρτέλα της MELAS για όλα.','Ο οργανισμός, η συζήτηση και το έργο δεν είναι η ίδια οντότητα.'],
 ['Δεν εμφανίζεται η διοικητική επιλογή που βλέπεις στην εκπαιδευτική εικόνα.','Ελέγχω τον ρόλο με τον διαχειριστή χωρίς κοινή χρήση κωδικών.','Αλλάζω τη διεύθυνση μέχρι να ανοίξει η λειτουργία.','Συνδέομαι με λογαριασμό εκπαιδευτή που έχει περισσότερες επιλογές.','Θεωρώ ότι η εικόνα εγγυάται δικαίωμα πρόσβασης.','Οι εκπαιδευτικές εικόνες δεν αντικαθιστούν τον έλεγχο ρόλων.'],
 ['Μετά την εναλλαγή CRM εμφανίζεται ξανά φόρμα σύνδεσης.','Ελέγχω σωστό ασφαλές περιβάλλον και αν έχει λήξει η αντίστοιχη συνεδρία.','Θεωρώ ότι χάθηκαν όλες οι καρτέλες και τις δημιουργώ ξανά.','Στέλνω τον κωδικό σε συνάδελφο για έλεγχο.','Απενεργοποιώ τον έλεγχο πρόσβασης ώστε να λειτουργεί ο διακόπτης.','Η συνεδρία του άλλου χώρου μπορεί να έχει λήξει χωρίς απώλεια δεδομένων.']
 ],
 'dcrm-customer'=>[
 ['Βρίσκεις ίδιο τηλέφωνο με διαφορετικό διακριτικό τίτλο.','Ελέγχω αν αφορά την ίδια νομική εταιρεία πριν δημιουργήσω ή τροποποιήσω καρτέλα.','Δημιουργώ νέα εταιρεία επειδή διαφέρει το εμφανιζόμενο όνομα.','Συγχωνεύω αυτόματα επειδή συμπίπτει ένα τηλέφωνο.','Αντιγράφω το ΑΦΜ της παλιάς καρτέλας χωρίς επιβεβαίωση.','Η πιθανή ταύτιση χρειάζεται επαλήθευση και δεν αποδεικνύεται από ένα πεδίο.'],
 ['Δεν γνωρίζεις το ΑΦΜ αλλά το πεδίο χρειάζεται αληθή εταιρικά στοιχεία.','Ζητώ επιβεβαίωση και ακολουθώ τη διαδικασία για το ελλιπές στοιχείο.','Βάζω εννέα μηδενικά για να φαίνεται συμπληρωμένο.','Δανείζομαι το ΑΦΜ σχετικής επιχείρησης του ίδιου ιδιοκτήτη.','Υπολογίζω πιθανή τιμή από τη διεύθυνση της εταιρείας.','Η ευκολία αποθήκευσης δεν δικαιολογεί κατασκευή ταυτότητας.'],
 ['Ο πελάτης χρησιμοποιεί εμπορικό όνομα διαφορετικό από τη νομική επωνυμία.','Καταγράφω κάθε έννοια στο κατάλληλο πεδίο με επιβεβαιωμένα στοιχεία.','Αντικαθιστώ τη νομική επωνυμία με το συντομότερο όνομα.','Δημιουργώ χωριστή εταιρεία μόνο λόγω διαφορετικής ονομασίας.','Χρησιμοποιώ το όνομα του υπαλλήλου ως εταιρική επωνυμία.','Νομική ταυτότητα, διακριτικός τίτλος και πρόσωπο επαφής διαφέρουν.']
 ],
 'dcrm-communication'=>[
 ['Κάλεσες δύο φορές και δεν απάντησε κανείς.','Καταγράφω απόπειρες χωρίς να αποδώσω ενδιαφέρον ή απόρριψη.','Καταγράφω LOST λόγω επιβεβαιωμένης άρνησης.','Καταγράφω qualified επειδή ο αριθμός είναι ενεργός.','Καταγράφω συζήτηση με τον ιδιοκτήτη χωρίς επαφή.','Η απουσία απάντησης δεν τεκμηριώνει πρόθεση.'],
 ['Συμφωνήθηκε έλεγχος τεκμηρίωσης API την Παρασκευή. Ποια καταγραφή είναι πλήρης;','Ενέργεια, υπεύθυνος, ημερομηνία/ώρα και τι περιμένουμε από κάθε πλευρά.','Μόνο ενδιαφέρον 5/5 επειδή υπάρχει τεχνικό θέμα.','Μόνο «να ξαναπάρουμε» χωρίς χρόνο ή σκοπό.','WON επειδή αποδέχθηκε δεύτερη επικοινωνία.','Η συνέχεια χρειάζεται σαφή περιγραφή και όχι μόνο βαθμό ενδιαφέροντος.'],
 ['Ο πελάτης λέει ότι του αρέσει η πρόταση αλλά περιμένει έγκριση συνέταιρου.','Καταγράφω θετική ένδειξη και εκκρεμή απόφαση με επόμενο βήμα.','Δηλώνω WON λόγω θετικού σχολίου.','Θεωρώ ότι η έγκριση CEO υποκαθιστά τον συνέταιρο.','Αποθηκεύω την υπόθεση ως πληρωμένη.','Η θετική εντύπωση δεν είναι η τελική συμφωνία της διαδικασίας.']
 ],
 'dcrm-intake'=>[
 ['Η απαίτηση περιλαμβάνει σύνδεση με λογισμικό τρίτου, χωρίς τεκμηρίωση.','Καταγράφω ανάγκη και τεχνική εκκρεμότητα πριν κοστολογηθεί η υλοποίηση.','Θεωρώ ότι κάθε σύστημα διαθέτει έτοιμο API.','Υπόσχομαι σύνδεση στην τιμή του βασικού website.','Αφαιρώ τη λειτουργία χωρίς να ενημερώσω τον πελάτη.','Η απαίτηση δεν τεκμηριώνει ακόμη εφικτότητα ή κόστος.'],
 ['Η μετάφραση περιεχομένου δεν περιλαμβάνεται στο scope, αλλά ο πελάτης την περιμένει.','Διευκρινίζω την εξαίρεση και ζητώ συμφωνία ευθύνης ή αλλαγής.','Προχωρώ σιωπηρά με μία μόνο γλώσσα.','Τη θεωρώ δωρεάν για να μην αλλάξει η προσφορά.','Τη διαγράφω από το brief για να μη φανεί η διαφορά.','Το out-of-scope πρέπει να είναι σαφές και κοινά κατανοητό.'],
 ['Το brief έχει λειτουργίες αλλά κανένα κριτήριο αποδοχής.','Ζητώ τι θα θεωρηθεί επιτυχής παράδοση και ποιος θα το επιβεβαιώσει.','Θεωρώ επιτυχία μόνο τη δημοσίευση ενός URL.','Αφήνω την απόφαση αποκλειστικά στην αισθητική του πωλητή.','Χρησιμοποιώ την αρχική ημερομηνία ως απόδειξη ολοκλήρωσης.','Οι λειτουργίες χρειάζονται επαληθεύσιμη αποδοχή και αρμόδιο.']
 ],
 'dcrm-proposals'=>[
 ['Διορθώνεται μία σημαντική προθεσμία σε ήδη εγκεκριμένη πρόταση.','Παράγεται νέα έκδοση και επαναλαμβάνεται η κατάλληλη έγκριση.','Αρκεί το ίδιο όνομα αρχείου για να ισχύει η παλιά έγκριση.','Αρκεί να ενημερωθεί προφορικά μόνο ο πελάτης.','Η παλιά έγκριση καλύπτει κάθε μη οικονομική αλλαγή.','Και οι μη οικονομικοί όροι είναι μέρος του εγκεκριμένου περιεχομένου.'],
 ['Πρόταση έχει CEO approval αλλά δεν έχει σταλεί στον πελάτη.','Είναι εγκεκριμένη εσωτερικά, όχι ακόμη αποσταλείσα ή αποδεκτή.','Έχει ήδη γίνει αποδεκτή από τον πελάτη.','Θεωρείται ολοκληρωμένη παραγωγή του έργου.','Η έγκριση ισοδυναμεί με είσπραξη προκαταβολής.','Τα γεγονότα της εταιρικής και της πελατειακής διαδικασίας καταγράφονται χωριστά.'],
 ['Ζητείται επαναχρησιμοποίηση παλιού PDF για άλλη εταιρεία.','Ελέγχω στοιχεία, όρους και εξουσιοδότηση για νέο κατάλληλο έγγραφο.','Αλλάζω μόνο παραλήπτη email και στέλνω το παλιό.','Χρησιμοποιώ την παλιά έγκριση ως γενική έγκριση εταιρείας.','Κρατώ τα παλιά στοιχεία μέσα στο συνημμένο ως υπόδειγμα.','Περιεχόμενο, παραλήπτης και εγκρίσεις πρέπει να αντιστοιχούν στη νέα υπόθεση.']
 ]
 ];
}

function academy_challenge_question(array $row,string $seed): array {
    [$prompt,$correct,$b,$c,$d,$why]=$row;
    $options=[$correct,$b,$c,$d];$offset=hexdec(substr(hash('sha256',$seed),0,2))%4;
    $options=array_merge(array_slice($options,$offset),array_slice($options,0,$offset));
    return [$prompt,$options,(4-$offset)%4,$why];
}

function academy_b2b_challenges(): array {
 return [
 'di-prospecting'=>[
 ['Επιχείρηση έχει 120 reviews, Instagram και σύνδεσμο που οδηγεί σε marketplace. Τι έχεις τεκμηριώσει;','Σήματα καταλληλότητας, με ιδιόκτητο website ακόμη προς επιβεβαίωση.','Επιβεβαιωμένη πρόθεση αγοράς επειδή έχει ενεργή παρουσία.','Έτοιμη συμφωνία για e-shop επειδή χρησιμοποιεί marketplace.','Απουσία ανάγκης επειδή υπάρχει ήδη οποιοσδήποτε σύνδεσμος.','Η εξωτερική παρουσία δίνει αφετηρία έρευνας, όχι πρόθεση ή βέβαιο scope.'],
 ['Η εταιρεία έχει πολύ καλό fit αλλά η καταλληλότητα επικοινωνίας είναι άγνωστη.','Ολοκληρώνεται ο προβλεπόμενος έλεγχος πριν από κλήση.','Γίνεται μία δοκιμαστική κλήση για να ελεγχθεί η επιθυμία.','Αντικαθίσταται η κλήση με μη ζητημένο μήνυμα.','Το fit χρησιμοποιείται ως επαρκής άδεια επικοινωνίας.','Η εμπορική καταλληλότητα δεν υποκαθιστά την εγκεκριμένη διαδικασία επικοινωνίας.'],
 ['Ποια σημείωση διαχωρίζει καλύτερα γεγονός και υπόθεση;','Ενεργές φωτογραφίες έργων· δεν εντοπίστηκε portfolio· να επιβεβαιωθεί πώς τα παρουσιάζουν.','Δεν έχουν σωστή παρουσία και σίγουρα χάνουν πελάτες.','Χρειάζονται e-shop γιατί δραστηριοποιούνται επαγγελματικά.','Θα αγοράσουν επειδή οι ανταγωνιστές έχουν website.','Η καλή έρευνα οδηγεί σε ερώτηση, όχι σε αυθαίρετη βεβαιότητα.']
 ],
 'di-opening'=>[
 ['Λες ότι δεν βρήκες site και ο ιδιοκτήτης σου δίνει το νέο του URL.','Αναγνωρίζω τη διόρθωση και επανεξετάζω αν υπάρχει σχετική ανάγκη.','Συνεχίζω το έτοιμο pitch για επιχειρήσεις χωρίς ιστοσελίδα.','Θεωρώ το site ανεπαρκές χωρίς να το έχω δει.','Καταγράφω ενδιαφέρον επανακατασκευής επειδή απάντησε.','Η νέα πληροφορία αλλάζει την αρχική υπόθεση και πρέπει να ενημερώσει τη συζήτηση.'],
 ['Η γραμματεία ρωτά τον σκοπό της κλήσης.','Εξηγώ την εμπορική συζήτηση για την online παρουσία και ζητώ τον αρμόδιο.','Λέω ότι είναι προσωπικό θέμα για να συνδεθώ πιο γρήγορα.','Υπονοώ ότι υπάρχει ήδη συμφωνία με τον ιδιοκτήτη.','Αποφεύγω την εταιρική ταυτότητα μέχρι να μιλήσει ο ιδιοκτήτης.','Η πρόσβαση στον αρμόδιο δεν πρέπει να επιτυγχάνεται με παραπλάνηση.'],
 ['Ο ιδιοκτήτης έχει μόνο 20 δευτερόλεπτα.','Δίνω σύντομο αληθινό πλαίσιο και ρωτώ αν υπάρχει λόγος για κατάλληλη συνέχεια.','Απαριθμώ όλες τις υπηρεσίες όσο πιο γρήγορα γίνεται.','Θεωρώ ότι αποδέχθηκε πλήρη παρουσίαση επειδή δεν έκλεισε.','Δίνω τελική τιμή χωρίς να μάθω το ζητούμενο.','Σύντομη συνάφεια και σεβασμός χρόνου προηγούνται του πλήρους pitch.']
 ],
 'di-listening'=>[
 ['«Θέλω φόρμα γιατί τα αιτήματα έρχονται σκόρπια». Ποια διευκρίνιση είναι πιο χρήσιμη;','Ποια στοιχεία χρειάζεστε από κάθε αίτημα και ποιος το αναλαμβάνει;','Ποιο χρώμα προτιμάτε για το κουμπί αποστολής;','Θέλετε αμέσως και ηλεκτρονικό κατάστημα;','Να σας εγγυηθούμε διπλάσια αιτήματα;','Πρώτα κατανοούμε τη ροή και το επιθυμητό αποτέλεσμα, όχι μόνο την εμφάνιση.'],
 ['Ο πελάτης λέει ότι στέλνει φωτογραφίες σε εταιρικούς αγοραστές.','Διερευνώ αν θέλει οργανωμένο κατάλογο, αιτήματα προσφοράς ή πραγματικές online συναλλαγές.','Καταγράφω e-shop με πληρωμές ως συμφωνημένο.','Προτείνω μόνο περισσότερες αναρτήσεις χωρίς ερώτηση.','Συμπεραίνω ότι δεν χρειάζεται website επειδή στέλνει φωτογραφίες.','Η ίδια σημερινή πρακτική μπορεί να οδηγεί σε διαφορετικό κατάλληλο scope.'],
 ['Μετά την παράφρασή σου ο πελάτης διορθώνει τον στόχο.','Υιοθετώ τη διόρθωση και επιβεβαιώνω τη νέα σύνοψη.','Κρατώ την πρώτη εκδοχή επειδή είναι πιο εύκολη στην πώληση.','Καταγράφω και τις δύο ως συμφωνημένες απαιτήσεις.','Αποφεύγω άλλη διευκρίνιση για να μη χαθεί χρόνος.','Η παράφραση είναι έλεγχος κατανόησης, όχι επιβολή ερμηνείας.']
 ],
 'di-value'=>[
 ['Ο πελάτης έχει αρκετή δουλειά και κουράζεται να απαντά τις ίδιες ερωτήσεις.','Συνδέω οργανωμένες πληροφορίες με ευκολότερη ενημέρωση πριν από επικοινωνία.','Υπόσχομαι κυρίως αύξηση αριθμού πελατών.','Παρουσιάζω όλα τα τεχνικά χαρακτηριστικά ανεξαρτήτως ανάγκης.','Επιμένω ότι κάθε επιχείρηση πρέπει να θέλει περισσότερη κίνηση.','Η αξία προκύπτει από την ανάγκη που περιέγραψε, όχι από ένα γενικό επιχείρημα.'],
 ['Ζητά λειτουργικό demo με πληρωμές πριν οποιαδήποτε συμφωνία. Οι όροι δεν έχουν οριστεί.','Ζητώ εγκεκριμένο scope και όρια demo πριν υποσχεθώ το παραδοτέο.','Δέχομαι επειδή το εγχειρίδιο γράφει «βλέπετε πρώτα».','Υπόσχομαι δωρεάν ανάπτυξη μέχρι να κάνει την πρώτη πώληση.','Παραλείπω το αίτημα από το brief και αφήνω την ομάδα να αποφασίσει.','Η εμπορική κατεύθυνση δεν είναι απεριόριστη δωρεάν παροχή.'],
 ['«Ναι, να δω μια πρόταση». Ποια δέσμευση υπάρχει;','Αποδοχή παρουσίασης, όχι ακόμη τιμής ή έναρξης υλοποίησης.','Οριστική αποδοχή όλων των τεχνικών όρων.','Έγκριση τιμολόγησης της τελικής κατασκευής.','Αυτόματο δικαίωμα χρήσης κάθε demo χωρίς συμφωνία.','Μικρό επόμενο βήμα και τελική αγορά είναι διαφορετικές αποφάσεις.']
 ],
 'di-objections'=>[
 ['«Είναι ακριβό» και η ανταγωνιστική προσφορά περιλαμβάνει λιγότερες λειτουργίες.','Επιβεβαιώνω τη διαφορά scope και τι θεωρεί απαραίτητο πριν συζητηθεί τιμή.','Δίνω αμέσως ίδια τιμή χωρίς αλλαγή αντικειμένου.','Δηλώνω ότι ο ανταγωνιστής δεν μπορεί να παραδώσει.','Προσθέτω δωρεάν λειτουργίες για να δικαιολογηθεί το αρχικό ποσό.','Η σύγκριση χρειάζεται κοινή βάση και πραγματική αιτία της επιφύλαξης.'],
 ['«Το παλιό site δεν έφερε πελάτες».','Ρωτώ τι περίμενε, τι μετρούσε και τι θεωρεί ότι δεν λειτούργησε.','Εγγυώμαι ότι το νέο θα αποδώσει επειδή είναι σύγχρονο.','Προτείνω αμέσως μεγαλύτερο site ως λύση.','Αποδίδω την αποτυχία στον προηγούμενο συνεργάτη χωρίς στοιχεία.','Η εμπειρία πρέπει να κατανοηθεί πριν προταθεί διαφορετική λύση.'],
 ['Μετά από μια διευκρίνιση επιμένει «δεν θέλω να προχωρήσω».','Κλείνω ευγενικά και καταγράφω την πραγματική έκβαση.','Ξεκινώ δεύτερο και τρίτο κύκλο αντιρρήσεων.','Αναθέτω σε συνάδελφο να ξαναπάρει αμέσως.','Σημειώνω HOT επειδή απάντησε σε διευκρίνιση.','Η συζήτηση δεν είναι μάχη επιμονής· η καθαρή άρνηση γίνεται σεβαστή.']
 ],
 'di-followup'=>[
 ['Ζήτησε σχετικό email αλλά δεν συμφώνησε νέα κλήση.','Καταγράφω ζητημένο υλικό και μη επιβεβαιωμένο follow-up.','Δηλώνω ραντεβού για την ώρα που με βολεύει.','Καταγράφω WON επειδή έδωσε email.','Θεωρώ γενική άδεια για καθημερινά μηνύματα.','Η αποστολή υλικού και το επιβεβαιωμένο ραντεβού είναι χωριστά γεγονότα.'],
 ['Στις 10:55 εκκρεμεί υλικό για συμφωνημένη παρουσίαση στις 11:00.','Συντονίζομαι και ενημερώνω ειλικρινά για την εκκρεμότητα και τη συνέχεια.','Παραλείπω το ραντεβού και ξεκινώ νέες κλήσεις.','Λέω ότι το email στάλθηκε, παρότι δεν στάλθηκε.','Μεταφέρω μόνος μου το ραντεβού χωρίς ενημέρωση.','Η συνέπεια περιλαμβάνει έγκαιρη διαχείριση καθυστέρησης, όχι απόκρυψη.'],
 ['Ποιο άνοιγμα follow-up συνδέεται καλύτερα με την προηγούμενη συζήτηση;','Είχαμε συμφωνήσει να δούμε σήμερα το portfolio· ποιο μέρος καλύπτει τις ανάγκες σας;','Είδατε το email; Να σας πω από την αρχή όλες τις υπηρεσίες;','Σας καλώ ξανά γιατί χρειάζομαι μια απάντηση σήμερα.','Η πρόταση θεωρείται αποδεκτή εφόσον την παραλάβατε.','Πλαίσιο, συμφωνημένος λόγος και χρήσιμη ερώτηση συνεχίζουν τη σχέση.']
 ],
 'di-sectors'=>[
 ['Χονδρέμπορος ζητά κατάλογο προϊόντων για αιτήματα τιμής.','Διευκρινίζω αν χρειάζεται παρουσίαση/RFQ ή συναλλαγές με online πληρωμή.','Προσθέτω πληρωμές ως αυτονόητο μέρος κάθε καταλόγου.','Υπόσχομαι σύνδεση αποθήκης πριν ελεγχθεί το λογισμικό.','Θεωρώ ίδια λύση με έναν προσωπικό φωτογραφικό ιστότοπο.','Ο κατάλογος δεν είναι κατ’ ανάγκη e-shop· η ροή αγοράς ορίζει το scope.'],
 ['Κατάλυμα ζητά κρατήσεις, αλλά χρησιμοποιεί ήδη εξωτερικό σύστημα.','Ρωτώ αν θέλει σύνδεσμο, αίτημα ή διασύνδεση με διαθεσιμότητα και πληρωμές.','Θεωρώ ότι η υπάρχουσα πλατφόρμα συνδέεται χωρίς έλεγχο.','Προτείνω να καταργηθεί η πλατφόρμα χωρίς να δω τη λειτουργία.','Δίνω την τιμή μιας απλής φόρμας για οποιαδήποτε μορφή κράτησης.','Οι διαφορετικές έννοιες κράτησης έχουν διαφορετικό τεχνικό αντικείμενο.'],
 ['Ιατρείο ζητά ισχυρισμούς αποτελεσματικότητας που δεν έχουν εγκριθεί.','Ζητώ εγκεκριμένο περιεχόμενο και κατάλληλο αρμόδιο έλεγχο.','Τους γράφω πιο έντονα για να αυξηθεί η πειστικότητα.','Αντιγράφω αντίστοιχους ισχυρισμούς από ανταγωνιστή.','Θεωρώ ότι η τελική ευθύνη πελάτη αρκεί χωρίς καμία διευκρίνιση.','Η πώληση website δεν παρέχει εξουσία δημιουργίας μη ελεγμένων επαγγελματικών αξιώσεων.']
 ],
 'di-compliance'=>[
 ['Υπάρχει παλιό ενδιαφέρον, αλλά σήμερα ζητήθηκε «καμία άλλη προώθηση».','Σταματώ άμεσα και δρομολογώ κεντρική καταγραφή αποκλεισμού.','Στέλνω πρώτα το έτοιμο demo επειδή είχε προηγηθεί ενδιαφέρον.','Ζητώ από άλλον υπάλληλο να τηλεφωνήσει για διευκρίνιση.','Αλλάζω την επαφή σε email χωρίς άλλη ενέργεια.','Το σημερινό σαφές αίτημα δεν παρακάμπτεται από προηγούμενη συζήτηση.'],
 ['Ζήτησε μία παρουσίαση με email. Ποια χρήση είναι συμβατή με το αίτημα;','Αποστολή του συγκεκριμένου ζητημένου υλικού με καταγραφή του αιτήματος.','Αυτόματη ένταξη σε όλες τις μελλοντικές καμπάνιες.','Διανομή του email σε συνεργάτες για δικές τους προσφορές.','Αποστολή και από προσωπικούς λογαριασμούς για μεγαλύτερη πιθανότητα ανάγνωσης.','Το συγκεκριμένο αίτημα δεν είναι γενική άδεια για κάθε προώθηση.'],
 ['Έστειλες κατά λάθος στοιχεία σε διαφορετικό παραλήπτη.','Ενημερώνω αμέσως τον αρμόδιο με ακριβή γεγονότα και ακολουθώ τη διαδικασία.','Διαγράφω μόνο το απεσταλμένο και θεωρώ ότι λύθηκε.','Περιμένω να δω αν θα παραπονεθεί κάποιος.','Αλλάζω τις σημειώσεις ώστε να μη φαίνεται η αποστολή.','Το περιστατικό χρειάζεται έγκαιρο υπεύθυνο χειρισμό, όχι απόκρυψη.']
 ],
 'di-performance'=>[
 ['100 κλήσεις, 40 συνομιλίες, 20 αρμόδιοι, 8 qualified. Ποιο είναι το qualification rate προς αρμόδιους;','40%','8%','20%','50%','8/20=40%. Τα άλλα ποσοστά χρησιμοποιούν διαφορετικό παρονομαστή.'],
 ['Δεν παρουσιάστηκε καμία πρόταση στην περίοδο. Πώς δείχνεις proposal-to-sale;','Μη διαθέσιμο για τον συγκεκριμένο παρονομαστή.','0% επειδή δεν υπήρξε παρουσίαση.','100% επειδή δεν χάθηκε καμία πρόταση.','Το ποσοστό της προηγούμενης περιόδου χωρίς σχετική ένδειξη.','Μηδενικός παρονομαστής δεν παράγει έγκυρο ποσοστό.'],
 ['Περισσότερες κλήσεις, λιγότερα έγκαιρα follow-ups και ελλιπείς σημειώσεις.','Ελέγχω φόρτο και ποιότητα μαζί με τον όγκο, πριν αξιολογήσω βελτίωση.','Θεωρώ επιτυχία αποκλειστικά την αύξηση κλήσεων.','Αλλάζω τα παλιά statuses για να αυξηθεί η μετατροπή.','Θέτω ακόμη μεγαλύτερο όγκο χωρίς εξέταση της διαδρομής.','Οι KPI πρέπει να οδηγούν σε διάγνωση και όχι σε κίνητρο για κακή καταγραφή.']
 ],
 'di-coaching'=>[
 ['Ο μαθητής γνωρίζει το script αλλά δεν κάνει παράφραση. Ποια εξάσκηση είναι στοχευμένη;','Σύντομα περιστατικά με σύνοψη της ανάγκης και άμεση ανατροφοδότηση.','Αποστήθιση μεγαλύτερου καταλόγου υπηρεσιών.','Άμεση επικοινωνία με πραγματικούς πελάτες χωρίς προηγούμενο έλεγχο.','Επανεξέταση μέχρι 100% χωρίς διατήρηση πρώτου βαθμού.','Η εξάσκηση πρέπει να στοχεύει τη δεξιότητα που λείπει.'],
 ['Ο υπεύθυνος βλέπει χαμηλές συνδέσεις σε όλη την ομάδα με νέα λίστα.','Ελέγχει ποιότητα λίστας και χρόνο κλήσεων πριν αποδώσει το πρόβλημα ατομικά.','Συμπεραίνει ότι όλοι ξέχασαν το ίδιο script.','Αξιολογεί μόνο τον εργαζόμενο με τις λιγότερες κλήσεις.','Αλλάζει τα αποτελέσματα ώστε η εβδομάδα να συγκρίνεται καλύτερα.','Κοινό μοτίβο μπορεί να προέρχεται από διαδικασία ή δεδομένα.'],
 ['Ολοκλήρωσες τη θεωρία. Τι ακολουθεί στην τρέχουσα Academy;','Οι προβλεπόμενες αξιολογήσεις και εικονική πρακτική, χωρίς αυτόματη εξουσιοδότηση CRM.','Υποχρεωτική κλήση σε πραγματικό υποψήφιο ως μέρος του quiz.','Αυτόματη πρόσβαση σε όλους τους πελάτες επειδή διάβασες το υλικό.','Παράκαμψη εγγράφων και τελικής έγκρισης μετά από ένα quiz.','Διατηρείται η εγκεκριμένη διαδρομή εκπαίδευσης, εγγράφων και ξεχωριστής πρόσβασης.']
 ],
 'dcrm-web-pipeline'=>[
 ['Η υποδοχή ζήτησε email, ο ιδιοκτήτης λείπει και δεν υπάρχει ραντεβού.','Καταγράφω αίτημα υλικού, ρόλο συνομιλητή και εκκρεμή διαδρομή προς τον αρμόδιο.','Καταγράφω HOT με επιβεβαιωμένη απόφαση ιδιοκτήτη.','Δηλώνω πρόταση αποδεκτή επειδή δόθηκε εταιρικό email.','Δηλώνω ως συμφωνημένη επανάκληση τον χρόνο που πρότεινε η υποδοχή, χωρίς επιβεβαίωση του αρμοδίου.','Η καρτέλα πρέπει να αντανακλά τα πραγματικά στοιχεία και τα ανοικτά σημεία.'],
 ['Ένα εγχειρίδιο δείχνει fit score, αλλά δεν υπάρχει τέτοιο πεδίο στην τρέχουσα οθόνη.','Αποτυπώνω τεκμήρια στα διαθέσιμα πεδία χωρίς να ισχυρίζομαι αυτόματο υπολογισμό.','Δηλώνω ότι το 5/5 είναι αυτόματα ο ίδιος δείκτης.','Χρησιμοποιώ την κλίμακα ενδιαφέροντος 1–5 και για fit, χωρίς να διαχωρίσω τις δύο έννοιες.','Κρατώ τη βαθμολόγηση μόνο σε προσωπικό αρχείο, χωρίς τεκμήρια στην κοινή καρτέλα.','Η επιχειρησιακή έννοια πρέπει να ξεχωρίζει από την πραγματική λειτουργία του συστήματος.'],
 ['Η ίδια επιχείρηση εμφανίζεται ξανά σε νέα λίστα.','Ελέγχω ιστορικό και συντονίζω υπεύθυνο πριν από νέα κίνηση.','Δημιουργώ νέα καρτέλα για να καταγραφεί ως νέο prospect.','Ξεκινώ από τη νεότερη λίστα και ελέγχω το παλιό ιστορικό μόνο αν απαντήσει ο πελάτης.','Καλώ χωρίς έλεγχο επειδή η λίστα είναι καινούρια.','Νέα λίστα δεν καταργεί την προηγούμενη σχέση ή τυχόν περιορισμό.']
 ],
 'dcrm-web-handoff'=>[
 ['Ο πελάτης περιμένει δύο γλώσσες, το brief γράφει μία.','Επιλύω τη διαφορά scope και ευθυνών πριν συνεχιστεί η πρόταση.','Περιμένω την παρουσίαση για να δω αν θα το παρατηρήσει.','Προσθέτω δεύτερη γλώσσα χωρίς έλεγχο κόστους ή υλικού.','Κρατώ μία γλώσσα ως παραδοχή και μεταφέρω τη δεύτερη σε μελλοντική φάση χωρίς νέα επιβεβαίωση.','Οι ασυμφωνίες πρέπει να λυθούν, όχι να μεταφερθούν στην παράδοση.'],
 ['Το site είναι καλαίσθητο, αλλά η φόρμα αιτήματος δεν λειτουργεί.','Το κρίσιμο πρόβλημα διορθώνεται και επανελέγχεται πριν από παράδοση.','Παραδίδεται ως ολοκληρωμένο επειδή η αισθητική εγκρίθηκε.','Παραδίδω ως ολοκληρωμένο, προτείνοντας προσωρινά τηλεφωνικά αιτήματα μέχρι να διορθωθεί η φόρμα.','Η φόρμα θεωρείται εκτός ελέγχου αφού δεν τη δοκίμασε ο πελάτης.','Το QC ελέγχει πραγματικές διαδρομές και υποσχέσεις, όχι μόνο εμφάνιση.'],
 ['«Μου αρέσει το demo, θα μιλήσω με τον συνέταιρο για τους όρους».','Καταγράφω feedback και εκκρεμή εμπορική απόφαση.','Δηλώνω WON και πλήρη αποδοχή τιμής.','Ξεκινώ παραγωγή θεωρώντας τη σιωπή αποδοχή.','Κλείνω την ευκαιρία ως WON και σημειώνω ότι οι οικονομικοί όροι θα οριστικοποιηθούν μετά.','Η θετική εντύπωση δεν υποκαθιστά την εγκεκριμένη εμπορική ολοκλήρωση.']
 ]
 ];
}
